float raymarch(in vec3 ro, in vec3 rd, in float maxDist) {
  float t = 0.0;
  for (int i = 0; i < 96; i++) {
    vec3 p = ro + rd * t;
    float d = mapScene(p);
    if (d < 0.001) return t; // Hit surface
    t += d;                  // Step forward by guaranteed safe distance
    if (t > maxDist) break;
  }
  return -1.0; // Missed
}

