// Narkowicz 2015 fitted ACES Film curve (Academy Color Encoding System)
vec3 acesFilm(in vec3 x) {
  const float a = 2.51;
  const float b = 0.03;
  const float c = 2.43;
  const float d = 0.59;
  const float e = 0.14;
  return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

// Linear sRGB to sRGB display gamma 2.2
vec3 linearToScreen(in vec3 col) {
  return pow(col, vec3(1.0 / 2.2));
}

